from decimal import Decimal, ROUND_HALF_UP
from .policy import TAG_STEP, MARKUP

def tag_price(wholesale):
    amount = Decimal(wholesale) * MARKUP
    return amount.quantize(TAG_STEP, rounding=ROUND_HALF_UP)

def accounting_price(wholesale):
    return Decimal(wholesale) * MARKUP
